import {loadHistoryData} from "./history-data.js";
import {ERA_SLUGS,eraFromLocation,navigateToEra} from "./history-routing.js";
const $=s=>document.querySelector(s),esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));async function main(){const data=await loadHistoryData();const eras=data.eras;const slugs=ERA_SLUGS;const basePath=new URL("./history/",import.meta.url).pathname;let active=eraFromLocation(basePath);if(!eras.some(e=>e.id===active))active=eras[0].id;let hasRenderedScale=false;let scrollSelectionTimer=null;let suppressStripScroll=false;let suppressReleaseTimer=null;const stripEl=$("#era-strip");const markers=document.createElement("div");markers.className="kb-era-tickmarks";markers.setAttribute("aria-hidden","true");markers.innerHTML='<span class="kb-era-tick kb-era-tick-prev"></span><span class="kb-era-tick kb-era-tick-current"></span><span class="kb-era-tick kb-era-tick-next"></span>';stripEl.insertAdjacentElement("afterend",markers);const ticks=Array.from(markers.children);let lastTickIndex=0;const updateTickPosition=()=>{const chips=Array.from(stripEl.querySelectorAll(".era[data-id]"));if(!chips.length)return;const inset=parseFloat(getComputedStyle(stripEl).paddingLeft||"0");const anchor=stripEl.scrollLeft+inset;let i=0;while(i<chips.length-2&&chips[i+1].offsetLeft<anchor)i++;const start=chips[i].offsetLeft,end=chips[Math.min(i+1,chips.length-1)].offsetLeft;const fraction=end>start?Math.max(0,Math.min(1,(anchor-start)/(end-start))):0;const position=i+fraction;const windowStart=Math.max(0,Math.min(chips.length-3,Math.round(position)-1));const local=Math.max(0,Math.min(2,position-windowStart));markers.style.setProperty("--kb-tick-x",String(local*28)+"px");ticks.forEach((tick,n)=>{const idx=windowStart+n;tick.style.opacity=String(Math.max(.23,1-Math.abs(position-idx)*.72));tick.style.transform="scaleX("+String(Math.max(.7,1-Math.abs(position-idx)*.3))+")"});lastTickIndex=Math.round(position)};const updateMarkers=id=>{markers.dataset.active=String(eras.findIndex(e=>e.id===id));updateTickPosition()};const focusEraChip=(id,behavior="smooth")=>{const chip=Array.from(stripEl.querySelectorAll(".era[data-id]")).find(el=>el.dataset.id===id);if(!chip)return;suppressStripScroll=true;clearTimeout(suppressReleaseTimer);const left=chip.offsetLeft-parseFloat(getComputedStyle(stripEl).paddingLeft||"0");stripEl.scrollTo({left,behavior});suppressReleaseTimer=setTimeout(()=>{suppressStripScroll=false},behavior==="smooth"?650:100)};const select=(id,move=false)=>{active=id;updateMarkers(id);const i=eras.findIndex(e=>e.id===id),era=eras[i],bib=i<6;$("#scale").innerHTML=eras.map((e,j)=>'<button aria-label="'+esc(e.title)+'" title="'+esc(e.title)+'" class="'+(e.date.precision==="undated"||e.date.precision==="debated"?"uncertain ":"")+(j===i?"active":"")+'" style="--c:'+esc(e.color)+'" data-id="'+esc(e.id)+'"></button>').join("");if(!hasRenderedScale){$("#scale").classList.add("kb-scale-enter");hasRenderedScale=true}else{$("#scale").classList.remove("kb-scale-enter")}$("#scale-numbers").innerHTML=eras.map((e,j)=>'<button class="'+(i===j?"active":"")+'" data-id="'+esc(e.id)+'" aria-label="Era '+(j+1)+': '+esc(e.title)+'" aria-current="'+(i===j?'step':'false')+'">'+(j+1)+'</button>').join("");$("#group-label").textContent=bib?"Historia bíblica":"Cristianismo";$("#group-count").textContent=bib?"6 eras":"4 eras";$("#selector .group-title").classList.toggle("christian",!bib);const detail=$("#era-detail");detail.style.removeProperty("min-height");const strip=$("#era-strip");strip.querySelectorAll(".era[data-id]").forEach(chip=>{chip.setAttribute("aria-pressed",String(chip.dataset.id===id))});{const ev=data.events.filter(e=>e.eraId===id).sort((a,b)=>a.order-b.order);detail.setAttribute("aria-busy","false");$("#era-detail").style.setProperty("--gc",bib?"var(--green)":"var(--gold)");const stories=(data.stories||[]).filter(x=>x.eraId===id).sort((a,b)=>a.order-b.order);const currentStory=stories.find(x=>location.pathname.includes("/"+x.id+"/"));const periods=(data.subEras||[]).filter(x=>x.eraId===id).sort((a,b)=>a.order-b.order);const periodNav=periods.length?'<nav class="kb-periods" aria-label="Periodos de la era"><button type="button" class="kb-period active" data-period="all" aria-pressed="true">Todos</button>'+periods.map(p=>'<button type="button" class="kb-period" data-period="'+esc(p.id)+'" aria-pressed="false">'+esc(p.title)+'</button>').join("")+'</nav>':"";const bookNav=bookLinks(era,new URL("./index.html",import.meta.url).pathname);const card=x=>storyCard(x,basePath+slugs[id]+"/"+x.id+"/",x.cover?.src?new URL("./"+x.cover.src,import.meta.url).pathname:"");if(stories.length){$("#era-detail").innerHTML=currentStory?renderEraSheet({era,body:'<a class="kb-story-back" href="'+basePath+slugs[id]+'/">← Todas las historias</a><p class="plate-kicker">'+esc(era.title)+' · '+currentStory.order+' de '+stories.length+'</p><h2>'+esc(currentStory.title)+'</h2><p class="plate-sub">'+esc(currentStory.reference)+'</p><p class="summary">'+esc(currentStory.summary)+'</p><a class="kb-read" href="'+new URL("./index.html",import.meta.url).pathname+'?book=genesis&chapter='+currentStory.chapter+'">Leer en Génesis ↗</a>',navigation:eraPager(eras,i)}):renderEraSheet({era,books:bookNav,body:'<section class="kb-story-section" aria-label="Relatos de '+esc(era.title)+'"><div class="kb-story-heading"><h3>Relatos</h3><span>'+stories.length+' '+(stories.length===1?'historia':'historias')+'</span></div><p class="kb-story-context">'+esc(era.subtitle)+'</p>'+periodNav+'<div class="kb-story-grid">'+stories.map(card).join("")+'</div></section>'+genesisPanel(data,id,basePath,slugs[id]),navigation:eraPager(eras,i)});if(!currentStory)initGenesisPanel($("#era-detail"));if(!currentStory&&periods.length){document.querySelectorAll(".kb-period").forEach(btn=>btn.addEventListener("click",()=>{const period=btn.dataset.period;document.querySelectorAll(".kb-period").forEach(b=>{const selected=b===btn;b.classList.toggle("active",selected);b.setAttribute("aria-pressed",String(selected))});document.querySelectorAll(".kb-story").forEach(card=>{const story=stories.find(x=>card.getAttribute("href").endsWith("/"+x.id+"/"));card.hidden=period!=="all"&&story?.subEraId!==period})}))}return}$("#era-detail").innerHTML=renderEraOverview({era,books:bookNav,navigation:eraPager(eras,i)});}};stripEl.addEventListener("scroll",()=>{updateTickPosition();if(suppressStripScroll)return;clearTimeout(scrollSelectionTimer);scrollSelectionTimer=setTimeout(()=>{if(suppressStripScroll)return;const inset=parseFloat(getComputedStyle(stripEl).paddingLeft||"0");const chips=Array.from(stripEl.querySelectorAll(".era[data-id]"));const closest=chips.reduce((best,chip)=>Math.abs(chip.offsetLeft-stripEl.scrollLeft-inset)<Math.abs(best.offsetLeft-stripEl.scrollLeft-inset)?chip:best,chips[0]);if(closest&&closest.dataset.id!==active){navigateToEra(basePath,closest.dataset.id);select(closest.dataset.id)}},130)} ,{passive:true});window.addEventListener("popstate",()=>{const id=eraFromLocation(basePath)||eras[0].id;select(id);focusEraChip(id,"instant")});document.body.addEventListener("click",e=>{const b=e.target.closest("button[data-id]");if(b?.dataset.id){const fromBottom=Boolean(b.closest(".kb-era-nav"));navigateToEra(basePath,b.dataset.id);select(b.dataset.id,true);focusEraChip(b.dataset.id);if(fromBottom)$("#era-detail").scrollIntoView({behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth",block:"start"})}});select(active);focusEraChip(active,"instant");updateTickPosition()}main().catch(e=>{$("#era-detail").innerHTML='<p>No se pudo cargar la cronología. <button onclick="location.reload()">Reintentar</button></p>';console.error(e)});